import { useResource, useField } from 'qortex-resource-react';

function ProfileForm() {
  const { resource, isChanged, isSaving, isValid, save, resetDraft } = useResource({
    initialData: { name: '', email: '' },
    validate: {
      on: 'blur',
      fields: {
        name: (v) => (!v ? 'Required' : null),
        email: (v) => (!v?.includes('@') ? 'Invalid email' : null),
      },
    },
    source: { save: (d) => api.saveProfile(d) },
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); save(); }}>
      <NameField resource={resource} />
      <EmailField resource={resource} />
      <button disabled={!isChanged || !isValid || isSaving}>
        {isSaving ? 'Saving…' : 'Save'}
      </button>
      <button type="button" onClick={resetDraft}>Reset</button>
    </form>
  );
}

function NameField({ resource }) {
  const { value, error, onChange, onBlur } = useField(resource, 'name');
  return (
    <>
      <input
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error && <span>{error}</span>}
    </>
  );
}

function EmailField({ resource }) {
  const { value, error, onChange, onBlur } = useField(resource, 'email');
  return (
    <>
      <input
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error && <span>{error}</span>}
    </>
  );
}

import { z } from 'zod';
import { zodResolver } from 'qortex-resource';
import { useResource, useField } from 'qortex-resource-react';

const Schema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
});

function UserEditor({ userId }: { userId: string }) {
  const { resource, isLoading, isChanged, save } = useResource({
    key: ['user', userId],
    validate: { resolver: zodResolver(Schema), on: 'blur' },
    persist: { draft: true },
    source: {
      fetch: () => api.getUser(userId),
      save: (d) => api.updateUser(userId, d),
    },
  });

  if (isLoading) return <p>Loading…</p>;
  return (
    <>
      <NameField resource={resource} />
      <button disabled={!isChanged} onClick={() => save()}>Save</button>
    </>
  );
}

import { createResourceHooks } from 'qortex-resource-react';

export const { useResource, useField } = createResourceHooks((userId: string) => ({
  key: ['user', userId],
  source: {
    fetch: () => api.getUser(userId),
    save: (d) => api.updateUser(userId, d),
  },
}));

function Page({ userId }) {
  useResource(userId);
  return <Name />;
}

function Name() {
  const { value, onChange, onBlur } = useField('name');
  return <input value={value ?? ''} onChange={(e) => onChange(e.target.value)} onBlur={onBlur} />;
}
